static Vcore_top_pipelined* top;
static int errors = 0;

static void tick() {
    top->clk = 0;
    top->eval();
    top->clk = 1;
    top->eval();
}

static uint32_t read_dmem_word(uint32_t byte_addr) {
    return top->rootp->core_top_pipelined__DOT__u_dmem__DOT__mem[byte_addr / 4];
}

static uint8_t read_dmem_byte(uint32_t byte_addr) {
    uint32_t word = read_dmem_word(byte_addr & ~0x3u);
    unsigned shift = (byte_addr & 0x3u) * 8;
    return (uint8_t)((word >> shift) & 0xFF);
}

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    top = new Vcore_top_pipelined;

    top->rst_n = 0;
    top->clk = 0;
    tick();
    tick();
    top->rst_n = 1;

    const uint32_t EK_ADDR = 0x1000;
    const uint32_t DK_ADDR = 0x1400;
    const uint32_t DONE_ADDR = 0x1800;
    const uint32_t DONE_MAGIC = 0xC0FFEE00u;

    const long MAX_CYCLES = 15000000;  // firmware pesado: 1 SHA3-512 + 4 XOF + 4 PRF + 4 NTT + productos
    bool done = false;

    time_t start_time = time(nullptr);

    for (long i = 0; i < MAX_CYCLES; i++) {
        tick();
        if (read_dmem_word(DONE_ADDR) == DONE_MAGIC) {
            done = true;
            std::printf("Firmware termino en el ciclo %ld\n", i);
            break;
        }
        if (i % 1000000 == 0 && i > 0) {
            std::printf("  ... %ld ciclos simulados (%.0f segundos reales)\n", i, difftime(time(nullptr), start_time));
        }
    }

    if (!done) {
        std::printf("FAIL [firmware_termina]: no se alcanzo el patron de status tras %ld ciclos\n", MAX_CYCLES);
        errors++;
    } else {
        std::printf("OK   [firmware_termina]\n");
    }

    if (done) {
        bool ek_ok = true;
        for (int i = 0; i < 800; i++) {
            uint8_t got = read_dmem_byte(EK_ADDR + i);
            if (got != expected_ek[i]) {
                ek_ok = false;
                std::printf("FAIL [ek_%d]: got=%u esperado=%u\n", i, got, expected_ek[i]);
                errors++;
            }
        }
        if (ek_ok) std::printf("OK   [ek_pke]: 800/800 bytes correctos\n");

        bool dk_ok = true;
        for (int i = 0; i < 768; i++) {
            uint8_t got = read_dmem_byte(DK_ADDR + i);
            if (got != expected_dk[i]) {
                dk_ok = false;
                std::printf("FAIL [dk_%d]: got=%u esperado=%u\n", i, got, expected_dk[i]);
                errors++;
            }
        }
        if (dk_ok) std::printf("OK   [dk_pke]: 768/768 bytes correctos\n");
    }

    delete top;

    if (errors == 0) {
        std::printf("\nPASS: k_pke_keygen.c corriendo en el core real produce el mismo resultado que la validacion nativa.\n");
        return 0;
    } else {
        std::printf("\nFAIL: %d error(es) detectado(s).\n", errors);
        return 1;
    }
}
